#include "cpuSw_usbDriver_usbDriver.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void cpuSw_usbDriver_usbDriver_initialize(void);
void cpuSw_usbDriver_usbDriver_notify(microkit_channel channel);
void cpuSw_usbDriver_usbDriver_timeTriggered(void);

volatile sb_queue_Common_DummyMessage_Impl_1_t *usbRecv_queue_1;
sb_queue_Common_DummyMessage_Impl_1_Recv_t usbRecv_recv_queue;
volatile sb_queue_Common_DummyMessage_Impl_1_t *usbSend_queue_1;

#define PORT_FROM_MON 0

bool usbRecv_is_empty(void) {
  return sb_queue_Common_DummyMessage_Impl_1_is_empty(&usbRecv_recv_queue);
}

bool get_usbRecv_poll(sb_event_counter_t *numDropped, Common_DummyMessage_Impl *data) {
  return sb_queue_Common_DummyMessage_Impl_1_dequeue((sb_queue_Common_DummyMessage_Impl_1_Recv_t *) &usbRecv_recv_queue, numDropped, data);
}

bool get_usbRecv(Common_DummyMessage_Impl *data) {
  sb_event_counter_t numDropped;
  return get_usbRecv_poll (&numDropped, data);
}

uintmax_t get_usbRecv_num_invalid(void) {
  return sb_queue_Common_DummyMessage_Impl_1_numInvalid((sb_queue_Common_DummyMessage_Impl_1_Recv_t *) &usbRecv_recv_queue);
}

bool put_usbSend(const Common_DummyMessage_Impl *data) {
  sb_queue_Common_DummyMessage_Impl_1_enqueue((sb_queue_Common_DummyMessage_Impl_1_t *) usbSend_queue_1, (Common_DummyMessage_Impl *) data);

  return true;
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_Common_DummyMessage_Impl_1_Recv_init(&usbRecv_recv_queue, (sb_queue_Common_DummyMessage_Impl_1_t *) usbRecv_queue_1);

  sb_queue_Common_DummyMessage_Impl_1_init((sb_queue_Common_DummyMessage_Impl_1_t *) usbSend_queue_1);

  cpuSw_usbDriver_usbDriver_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      cpuSw_usbDriver_usbDriver_timeTriggered();
      // Report that this dispatch has finished.  The _MON wrapper forwards it to
      // the scheduler.  The default scheduler ignores runtime signals from
      // partitions -- the schedule is static and each partition runs for its full
      // allotted time -- so this is inert there; the test scheduler uses it as the
      // slot-complete event, which is what lets it step as fast as threads run
      // rather than waiting out each slot's wall-clock budget.
      microkit_notify(PORT_FROM_MON);
      break;
    default:
      cpuSw_usbDriver_usbDriver_notify(channel);
  }
}
